const {classify}=require('./classify.cjs');exports.resume=(q,id)=>q.map(x=>x.id===id&&x.state==='uncertain'?{...x,state:'ready'}:x);exports.drain=async(q,post,persist)=>{const out=q.slice();for(const item of q){if(item.state!=='ready')continue;let res,err;try{res=await post(item)}catch(e){err=e}const bad=err?true:!!res&&typeof res.status==='number'&&(res.status<200||res.status>=300);if(!bad){out.splice(out.indexOf(item),1);continue}const outcome=classify(err||res);if(outcome==='rejected'){out[out.indexOf(item)]={...item,state:'rejected'};continue}out[out.indexOf(item)]={...item,state:'uncertain'};break}await persist(out);q.length=0;for(const item of out)q.push(item);return q;};
